-- Specialize the existing 28 module workspaces; never delete historical fields/records.
-- Apply on staged environments after 0052_restore_existing_account_access.sql.
BEGIN;
DO $$ BEGIN
 IF (SELECT count(*) FROM public.intranet_modules WHERE page_id = ANY(ARRAY['finance.transactions','finance.billing','finance.subscriptions','finance.guarantee','marketing.content','marketing.analytics','audit.reports','audit.sanctions','compliance.policies','compliance.risks','rse.packaging','rse.recycling','rse.co2','rse.esg','product.studio','product.integrations','product.documentation','product.innovation','security.infrastructure','security.environments','security.vpn','marketing.podcasts','rse.points','security.code','security.console','security.documentation','support.compliance','support.onboarding']::text[])) <> 28
 THEN RAISE EXCEPTION 'Missing prerequisite intranet modules for specialization'; END IF;
END $$;
UPDATE public.intranet_modules AS m
SET definition = m.definition || jsonb_build_object(
 'fields', specification.fields,
 'description', specification.description,
 'operationalNote', specification.operational_note,
 'recordLabel', specification.record_label
)
FROM (VALUES
  ('finance.transactions', '[{"key":"counterparty","label":"Tiers ou compte concerné","type":"text","required":true},{"key":"reference","label":"Référence de transaction","type":"text","required":true},{"key":"amount","label":"Montant observé","type":"number","required":true},{"key":"currency","label":"Devise","type":"text","required":true},{"key":"period","label":"Période comptable","type":"text","required":false},{"key":"lines","label":"Écritures et justificatifs associés","type":"lines","required":false},{"key":"booking_date","label":"Date de valeur","type":"date","required":false},{"key":"bank_reference","label":"Référence du prestataire de paiement","type":"text","required":false},{"key":"reconciliation_state","label":"État du rapprochement","type":"text","required":false},{"key":"payment_proof","label":"Référence de la preuve de paiement","type":"text","required":false}]'::jsonb, 'Contrôle et rapprochement des mouvements financiers déjà enregistrés.', 'Ce dossier complète le registre de transactions ; sa validation n''initie ni virement, ni remboursement, ni modification du solde bancaire.', 'revue de transaction'),
  ('finance.billing', '[{"key":"counterparty","label":"Client ou marchand facturé","type":"text","required":true},{"key":"reference","label":"Contrat, commande ou devis de référence","type":"text","required":true},{"key":"amount","label":"Montant de facturation","type":"number","required":true},{"key":"currency","label":"Devise de la facture","type":"text","required":true},{"key":"period","label":"Période facturée","type":"text","required":false},{"key":"lines","label":"Lignes et justificatifs de facturation","type":"lines","required":false},{"key":"invoice_number","label":"Numéro de facture","type":"text","required":false},{"key":"invoice_date","label":"Date d''émission envisagée","type":"date","required":false},{"key":"due_date","label":"Échéance de paiement","type":"date","required":false},{"key":"vat_treatment","label":"TVA et traitement fiscal","type":"text","required":false}]'::jsonb, 'Préparation et contrôle des factures commerciales, références et échéances.', 'Une fiche validée n''émet pas une facture fiscale, ne débite pas un client et ne crée aucun paiement Stripe. L''émission officielle nécessite un workflow dédié.', 'contrôle de facturation'),
  ('finance.subscriptions', '[{"key":"counterparty","label":"Marchand ou titulaire","type":"text","required":true},{"key":"reference","label":"Référence de l''abonnement","type":"text","required":true},{"key":"amount","label":"Montant contrôlé","type":"number","required":true},{"key":"currency","label":"Devise facturée","type":"text","required":true},{"key":"period","label":"Période d''abonnement","type":"text","required":false},{"key":"lines","label":"Contrôles et écarts constatés","type":"lines","required":false},{"key":"stripe_subscription_id","label":"Identifiant Stripe","type":"text","required":false},{"key":"plan_name","label":"Forfait concerné","type":"text","required":false},{"key":"billing_status","label":"Statut de facturation constaté","type":"text","required":false},{"key":"discrepancy","label":"Écart à régulariser","type":"textarea","required":false}]'::jsonb, 'Revue des abonnements et écarts de facturation, distincte du suivi Platform.', 'Le dossier ne souscrit, ne renouvelle ni ne résilie un abonnement Stripe ; les webhooks Platform restent autoritatifs.', 'contrôle d''abonnement'),
  ('finance.guarantee', '[{"key":"counterparty","label":"Bénéficiaire ou contrepartie","type":"text","required":true},{"key":"reference","label":"Référence du contrat de garantie","type":"text","required":true},{"key":"amount","label":"Montant de l''engagement","type":"number","required":true},{"key":"currency","label":"Devise de l''engagement","type":"text","required":true},{"key":"period","label":"Période de couverture","type":"text","required":false},{"key":"lines","label":"Éléments d''exposition et justificatifs","type":"lines","required":false},{"key":"coverage_terms","label":"Conditions et exclusions","type":"textarea","required":false},{"key":"claim_reference","label":"Référence d''une demande de garantie","type":"text","required":false},{"key":"eligibility_review","label":"Contrôle d''éligibilité","type":"textarea","required":false},{"key":"settlement_reference","label":"Preuve de décaissement externe","type":"text","required":false}]'::jsonb, 'Suivi des engagements de garantie, expositions et pièces justificatives.', 'L''approbation d''un dossier de fonds de garantie ne provisionne pas un compte et ne déclenche aucun versement ou remboursement.', 'engagement de garantie'),
  ('marketing.content', '[{"key":"channel","label":"Canal de destination","type":"text","required":true},{"key":"audience","label":"Public visé","type":"text","required":true},{"key":"content","label":"Texte, scénario ou brief","type":"textarea","required":true},{"key":"publication_date","label":"Date de publication prévue","type":"date","required":false},{"key":"budget","label":"Budget prévu","type":"number","required":false},{"key":"result","label":"Résultat observé","type":"number","required":false},{"key":"source","label":"Source de la mesure","type":"text","required":false},{"key":"format","label":"Format et déclinaisons","type":"text","required":false},{"key":"call_to_action","label":"Appel à l''action","type":"text","required":false},{"key":"rights_reference","label":"Droits et autorisations des médias","type":"text","required":false},{"key":"published_url","label":"Adresse de publication vérifiée","type":"text","required":false}]'::jsonb, 'Production, revue et calendrier des contenus de communication.', 'Un contenu validé reste interne tant qu''un outil de publication ne confirme pas explicitement sa mise en ligne.', 'contenu éditorial'),
  ('marketing.analytics', '[{"key":"indicator","label":"Indicateur et définition","type":"text","required":true},{"key":"period","label":"Période observée","type":"text","required":true},{"key":"channel","label":"Canal ou campagne","type":"text","required":true},{"key":"value","label":"Valeur relevée","type":"number","required":true},{"key":"unit","label":"Unité de mesure","type":"text","required":true},{"key":"source","label":"Source et date d''extraction","type":"text","required":true},{"key":"analysis","label":"Interprétation et limites","type":"textarea","required":false},{"key":"campaign_reference","label":"Référence campagne","type":"text","required":false},{"key":"attribution_window","label":"Fenêtre d''attribution","type":"text","required":false},{"key":"comparison_period","label":"Période de comparaison","type":"text","required":false},{"key":"action_recommended","label":"Action proposée","type":"textarea","required":false}]'::jsonb, 'Mesures documentées de performance des canaux et campagnes.', 'Les chiffres sont des saisies documentées. Ils ne constituent pas une synchronisation automatique avec les régies publicitaires.', 'mesure marketing'),
  ('audit.reports', '[{"key":"entity","label":"Entité auditée","type":"text","required":true},{"key":"reference","label":"Référence de mission","type":"text","required":false},{"key":"finding","label":"Synthèse des constats","type":"textarea","required":true},{"key":"evidence","label":"Éléments probants","type":"textarea","required":false},{"key":"corrective_action","label":"Recommandations","type":"textarea","required":true},{"key":"review_date","label":"Date de validation envisagée","type":"date","required":false},{"key":"auditor","label":"Auditeur principal","type":"text","required":false},{"key":"audit_scope","label":"Périmètre de mission","type":"textarea","required":false},{"key":"opinion","label":"Conclusion et réserves","type":"textarea","required":false},{"key":"corrective_plan_ref","label":"Référence du plan correctif","type":"text","required":false}]'::jsonb, 'Constitution de rapports d''audit et traçabilité des constats et preuves.', 'Un rapport validé ne clôt pas automatiquement les non-conformités ni les actions correctives ; ces objets conservent leur cycle de vie.', 'rapport d''audit'),
  ('audit.sanctions', '[{"key":"entity","label":"Entité ou partenaire concerné","type":"text","required":true},{"key":"reference","label":"Référence du contrôle","type":"text","required":false},{"key":"finding","label":"Faits et manquements constatés","type":"textarea","required":true},{"key":"evidence","label":"Pièces probantes","type":"textarea","required":false},{"key":"corrective_action","label":"Mesure proposée et justification","type":"textarea","required":true},{"key":"review_date","label":"Date de décision envisagée","type":"date","required":false},{"key":"legal_basis","label":"Fondement contractuel ou juridique","type":"text","required":false},{"key":"proportionality","label":"Analyse de proportionnalité","type":"textarea","required":false},{"key":"appeal_process","label":"Procédure contradictoire et recours","type":"textarea","required":false},{"key":"decision_authority","label":"Autorité compétente","type":"text","required":false}]'::jsonb, 'Instruction documentée des propositions de sanction et contrôle de leur proportionnalité.', 'Une approbation dans ce registre ne prononce aucune sanction contractuelle ou disciplinaire automatiquement ; la décision relève de l''autorité habilitée.', 'proposition de sanction'),
  ('compliance.policies', '[{"key":"entity","label":"Périmètre de la politique","type":"text","required":true},{"key":"requirement","label":"Objet et obligation","type":"textarea","required":true},{"key":"legal_reference","label":"Références juridiques","type":"text","required":false},{"key":"assessment","label":"Contenu et règles proposées","type":"textarea","required":true},{"key":"mitigation","label":"Plan de mise en œuvre","type":"textarea","required":false},{"key":"policy_version","label":"Version documentaire","type":"text","required":false},{"key":"effective_date","label":"Date d''entrée en vigueur prévue","type":"date","required":false},{"key":"target_audience","label":"Destinataires et équipes","type":"text","required":false},{"key":"publication_reference","label":"Référence du document approuvé","type":"text","required":false}]'::jsonb, 'Élaboration et révision contrôlées des politiques internes de conformité.', 'La validation du dossier ne publie pas automatiquement une politique, ni ne lui confère une date d''entrée en vigueur.', 'politique interne'),
  ('compliance.risks', '[{"key":"entity","label":"Activité ou entité exposée","type":"text","required":true},{"key":"requirement","label":"Scénario de risque","type":"textarea","required":true},{"key":"legal_reference","label":"Obligation ou norme concernée","type":"text","required":false},{"key":"assessment","label":"Analyse de l''exposition et de l''impact","type":"textarea","required":true},{"key":"mitigation","label":"Mesures de prévention et de traitement","type":"textarea","required":false},{"key":"likelihood","label":"Probabilité évaluée","type":"text","required":false},{"key":"severity","label":"Gravité évaluée","type":"text","required":false},{"key":"residual_risk","label":"Risque résiduel estimé","type":"text","required":false},{"key":"control_owner","label":"Responsable du contrôle","type":"text","required":false}]'::jsonb, 'Évaluation des risques juridiques, réglementaires et contractuels avec actions de maîtrise.', 'Une fiche de risque reste une évaluation interne ; elle ne certifie ni conformité réglementaire ni absence de risque.', 'risque de conformité'),
  ('rse.packaging', '[{"key":"period","label":"Période de contrôle","type":"text","required":true},{"key":"category","label":"Famille d''emballages","type":"text","required":true},{"key":"quantity","label":"Quantité contrôlée","type":"number","required":true},{"key":"unit","label":"Unité contrôlée","type":"text","required":true},{"key":"method","label":"Critères de contrôle et échantillonnage","type":"textarea","required":true},{"key":"source","label":"Fiche technique ou preuve fournisseur","type":"text","required":true},{"key":"material","label":"Composition et matériau","type":"text","required":false},{"key":"supplier_reference","label":"Fournisseur et référence","type":"text","required":false},{"key":"certification","label":"Norme ou certification vérifiée","type":"text","required":false},{"key":"decision_scope","label":"Limites de l''avis qualité","type":"textarea","required":false}]'::jsonb, 'Qualification des matériaux, emballages et preuves de conformité avant leur usage.', 'La validation d''une fiche n''homologue pas automatiquement l''emballage sur Platform et ne commande aucun stock.', 'dossier emballage'),
  ('rse.recycling', '[{"key":"period","label":"Période de collecte","type":"text","required":true},{"key":"category","label":"Matière et flux","type":"text","required":true},{"key":"quantity","label":"Masse ou volume collecté","type":"number","required":true},{"key":"unit","label":"Unité de mesure","type":"text","required":true},{"key":"method","label":"Méthode de pesée et périmètre","type":"textarea","required":true},{"key":"source","label":"Justificatif ou registre source","type":"text","required":true},{"key":"partner","label":"Collecteur ou partenaire","type":"text","required":false},{"key":"destination","label":"Filière de valorisation","type":"text","required":false},{"key":"receipt_reference","label":"Référence du bordereau","type":"text","required":false},{"key":"measurement_limits","label":"Limites et réserves","type":"textarea","required":false}]'::jsonb, 'Suivi des flux réellement collectés, pesés et orientés vers une filière de traitement.', 'Registre de mesures documentées : aucune collecte physique ni émission de certificat n''est déclenchée automatiquement.', 'mesure de recyclage'),
  ('rse.co2', '[{"key":"period","label":"Période de calcul","type":"text","required":true},{"key":"category","label":"Poste ou activité émettrice","type":"text","required":true},{"key":"quantity","label":"Valeur calculée","type":"number","required":true},{"key":"unit","label":"Unité (kgCO₂e, tCO₂e…)","type":"text","required":true},{"key":"method","label":"Méthode, périmètre et facteurs d''émission","type":"textarea","required":true},{"key":"source","label":"Origine du facteur d''émission","type":"text","required":true},{"key":"scope","label":"Périmètre d''émission","type":"text","required":false},{"key":"baseline","label":"Scénario de référence","type":"text","required":false},{"key":"assumptions","label":"Hypothèses et exclusions","type":"textarea","required":false},{"key":"uncertainty","label":"Incertitudes du calcul","type":"textarea","required":false}]'::jsonb, 'Traçabilité des estimations d''émissions et des hypothèses de calcul.', 'Les valeurs sont déclarées avec leur méthode et leur source. Ce registre n''est pas une mesure automatique des émissions de Platform.', 'calcul d''impact'),
  ('rse.esg', '[{"key":"period","label":"Exercice et période couverte","type":"text","required":true},{"key":"category","label":"Indicateur ESG","type":"text","required":true},{"key":"quantity","label":"Valeur rapportée","type":"number","required":true},{"key":"unit","label":"Unité et base de mesure","type":"text","required":true},{"key":"method","label":"Méthodologie de calcul","type":"textarea","required":true},{"key":"source","label":"Source primaire et traçabilité","type":"text","required":true},{"key":"framework","label":"Référentiel de publication","type":"text","required":false},{"key":"coverage","label":"Entités ou opérations couvertes","type":"text","required":false},{"key":"data_quality","label":"Fiabilité et limites","type":"textarea","required":false},{"key":"external_audit","label":"Référence de revue externe","type":"text","required":false}]'::jsonb, 'Constitution et validation des indicateurs de reporting extra-financier.', 'Les indicateurs ne deviennent pas des déclarations publiées ou auditées par leur simple validation interne.', 'indicateur ESG'),
  ('product.studio', '[{"key":"area","label":"Projet ou produit conçu","type":"text","required":true},{"key":"problem","label":"Brief et besoin utilisateur","type":"textarea","required":true},{"key":"acceptance","label":"Livrables et critères de validation","type":"textarea","required":true},{"key":"version","label":"Version de conception","type":"text","required":false},{"key":"dependency","label":"Dépendances techniques ou fournisseurs","type":"text","required":false},{"key":"result","label":"Résultat de revue et tests","type":"textarea","required":false},{"key":"prototype_reference","label":"Référence du prototype","type":"text","required":false},{"key":"supplier_constraints","label":"Contraintes de fabrication","type":"textarea","required":false},{"key":"design_review","label":"Décision de revue design","type":"textarea","required":false},{"key":"physical_sample","label":"Échantillon physique vérifié","type":"text","required":false}]'::jsonb, 'Dossiers de conception et coordination de projets créatifs distincts des demandes produit.', 'Une validation de conception ne lance aucune fabrication ou commande fournisseur sans approbation opérationnelle distincte.', 'dossier de conception'),
  ('product.integrations', '[{"key":"area","label":"Système ou parcours concerné","type":"text","required":true},{"key":"problem","label":"Besoin et événement déclencheur","type":"textarea","required":true},{"key":"acceptance","label":"Contrats et critères d''acceptation","type":"textarea","required":true},{"key":"version","label":"Version d''API ou de schéma","type":"text","required":false},{"key":"dependency","label":"Service et dépendances","type":"text","required":false},{"key":"result","label":"Résultat de recette vérifiable","type":"textarea","required":false},{"key":"source_system","label":"Système émetteur","type":"text","required":false},{"key":"target_system","label":"Système destinataire","type":"text","required":false},{"key":"idempotency_key","label":"Stratégie d''idempotence","type":"text","required":false},{"key":"retry_policy","label":"Échec, reprise et alerte","type":"textarea","required":false}]'::jsonb, 'Contrats d''API, dépendances, qualité des échanges et tests des intégrations.', 'Une fiche approuvée n''active aucune intégration. Les changements du bridge Platform/Intranet exigent leurs propres tests et validations.', 'intégration technique'),
  ('product.documentation', '[{"key":"area","label":"Produit ou module documenté","type":"text","required":true},{"key":"problem","label":"Documentation nécessaire","type":"textarea","required":true},{"key":"acceptance","label":"Critères de complétude et qualité","type":"textarea","required":true},{"key":"version","label":"Version couverte","type":"text","required":false},{"key":"dependency","label":"Références techniques","type":"text","required":false},{"key":"result","label":"Résultat de la vérification","type":"textarea","required":false},{"key":"document_url","label":"Référence du document source","type":"text","required":false},{"key":"document_owner","label":"Mainteneur documentaire","type":"text","required":false},{"key":"audience","label":"Public autorisé","type":"text","required":false},{"key":"review_cycle","label":"Périodicité de mise à jour","type":"text","required":false}]'::jsonb, 'Documentation produit versionnée, revue et maintenue dans son référentiel.', 'La fiche documente une demande : elle ne remplace pas la version officielle, ni ne rend publique une documentation confidentielle.', 'demande documentaire'),
  ('product.innovation', '[{"key":"area","label":"Opportunité ou domaine d''innovation","type":"text","required":true},{"key":"problem","label":"Problème utilisateur ou marché","type":"textarea","required":true},{"key":"acceptance","label":"Hypothèse et seuil de succès","type":"textarea","required":true},{"key":"version","label":"Itération de recherche","type":"text","required":false},{"key":"dependency","label":"Dépendances et ressources","type":"text","required":false},{"key":"result","label":"Résultats et enseignements","type":"textarea","required":false},{"key":"research_method","label":"Méthodologie d''étude","type":"textarea","required":false},{"key":"test_population","label":"Population ou échantillon","type":"text","required":false},{"key":"risk_assessment","label":"Limites, coûts et risques","type":"textarea","required":false},{"key":"next_decision","label":"Décision recommandée","type":"text","required":false}]'::jsonb, 'Hypothèses d''innovation, expérimentations et évaluation des opportunités.', 'L''approbation d''une étude de R&D ne modifie pas automatiquement la roadmap, le catalogue ou l''offre commerciale.', 'expérimentation R&D'),
  ('security.infrastructure', '[{"key":"asset","label":"Serveur, service ou équipement","type":"text","required":true},{"key":"environment","label":"Environnement concerné","type":"text","required":true},{"key":"finding","label":"Constat technique ou vulnérabilité","type":"textarea","required":true},{"key":"action","label":"Plan d''intervention ou de durcissement","type":"textarea","required":true},{"key":"verification","label":"Preuve de test ou de remédiation","type":"textarea","required":false},{"key":"review_date","label":"Date de prochaine revue","type":"date","required":false},{"key":"provider","label":"Hébergeur ou prestataire","type":"text","required":false},{"key":"service_owner","label":"Responsable technique","type":"text","required":false},{"key":"backup_policy","label":"Sauvegarde et rétention","type":"textarea","required":false},{"key":"recovery_test","label":"Dernier test de restauration","type":"text","required":false}]'::jsonb, 'Inventaire des composants d''infrastructure et revues de continuité et de sécurité.', 'L''approbation d''un dossier ne modifie pas l''infrastructure : intervention et preuve d''exécution doivent être réalisées dans l''outil technique autorisé.', 'revue d''infrastructure'),
  ('security.environments', '[{"key":"asset","label":"Application ou composant","type":"text","required":true},{"key":"environment","label":"Environnement cible","type":"text","required":true},{"key":"finding","label":"Changement ou risque constaté","type":"textarea","required":true},{"key":"action","label":"Plan d''intervention","type":"textarea","required":true},{"key":"verification","label":"Preuves de tests et contrôle","type":"textarea","required":false},{"key":"review_date","label":"Date de revue","type":"date","required":false},{"key":"release_reference","label":"Version ou commit ciblé","type":"text","required":false},{"key":"deployment_window","label":"Fenêtre d''intervention","type":"text","required":false},{"key":"rollback_plan","label":"Plan de retour arrière","type":"textarea","required":false},{"key":"execution_trace","label":"Lien vers le journal d''exécution","type":"text","required":false}]'::jsonb, 'Contrôles des environnements, changements et plans de retour arrière.', 'La validation d''un dossier n''exécute ni déploiement, ni rollback. L''action technique doit être tracée par le système de déploiement.', 'revue d''environnement'),
  ('security.vpn', '[{"key":"asset","label":"Ressource réseau demandée","type":"text","required":true},{"key":"environment","label":"Environnement concerné","type":"text","required":true},{"key":"finding","label":"Justification de l''accès","type":"textarea","required":true},{"key":"action","label":"Action et approbation requises","type":"textarea","required":true},{"key":"verification","label":"Preuve d''autorisation et de révocation","type":"textarea","required":false},{"key":"review_date","label":"Date de réexamen","type":"date","required":false},{"key":"beneficiary","label":"Bénéficiaire identifié","type":"text","required":false},{"key":"access_duration","label":"Durée d''accès demandée","type":"text","required":false},{"key":"ticket_reference","label":"Référence de demande IT","type":"text","required":false},{"key":"revocation_evidence","label":"Preuve de révocation","type":"text","required":false}]'::jsonb, 'Demandes et revues d''accès aux réseaux sécurisés.', 'Ce module documente les demandes et les contrôles. La validation n''ouvre aucun VPN ni ne provisionne un compte réseau.', 'revue d''accès VPN'),
  ('marketing.podcasts', '[{"key":"channel","label":"Plateforme de diffusion envisagée","type":"text","required":true},{"key":"audience","label":"Audience ciblée","type":"text","required":true},{"key":"content","label":"Synopsis, conducteur et intervenants","type":"textarea","required":true},{"key":"publication_date","label":"Date prévue de diffusion","type":"date","required":false},{"key":"budget","label":"Budget de production","type":"number","required":false},{"key":"result","label":"Écoutes confirmées","type":"number","required":false},{"key":"source","label":"Source des statistiques d''écoute","type":"text","required":false},{"key":"episode_number","label":"Numéro d''épisode","type":"text","required":false},{"key":"guest_consent","label":"Consentement et droits voix/image","type":"text","required":false},{"key":"audio_master","label":"Référence du fichier master","type":"text","required":false},{"key":"published_url","label":"Lien de diffusion confirmé","type":"text","required":false}]'::jsonb, 'Préparation, validation éditoriale et suivi des épisodes audio.', 'La validation du dossier n''enregistre, n''héberge et ne publie aucun épisode automatiquement.', 'épisode podcast'),
  ('rse.points', '[{"key":"period","label":"Période de simulation","type":"text","required":true},{"key":"category","label":"Action envisagée","type":"text","required":true},{"key":"quantity","label":"Volume simulé (non crédité)","type":"number","required":true},{"key":"unit","label":"Unité de simulation","type":"text","required":true},{"key":"method","label":"Règles de simulation et d''éligibilité","type":"textarea","required":true},{"key":"source","label":"Source des hypothèses","type":"text","required":true},{"key":"pilot_stage","label":"Stade du pilote","type":"text","required":false},{"key":"reward_policy","label":"Règles de récompense envisagées","type":"textarea","required":false},{"key":"fraud_controls","label":"Prévention des abus","type":"textarea","required":false},{"key":"platform_dependency","label":"Condition d''activation Platform","type":"textarea","required":false}]'::jsonb, 'Conception et contrôle du futur programme de points circulaires.', 'Programme non activé : aucune ligne de ce registre n''attribue des points à un client ou ne crédite un solde dans Platform.', 'hypothèse de fidélité'),
  ('security.code', '[{"key":"asset","label":"Dépôt ou composant logiciel","type":"text","required":true},{"key":"environment","label":"Branche et environnement","type":"text","required":true},{"key":"finding","label":"Changement ou risque constaté","type":"textarea","required":true},{"key":"action","label":"Correction ou contrôle attendu","type":"textarea","required":true},{"key":"verification","label":"Résultat CI et revue de sécurité","type":"textarea","required":false},{"key":"review_date","label":"Date de révision","type":"date","required":false},{"key":"commit_sha","label":"Référence de commit","type":"text","required":false},{"key":"pull_request_url","label":"Lien de pull request","type":"text","required":false},{"key":"secret_scanning","label":"Contrôle de secrets et dépendances","type":"textarea","required":false},{"key":"release_reference","label":"Version de livraison","type":"text","required":false}]'::jsonb, 'Contrôles des dépôts, changements de code et revues de sécurité applicative.', 'La validation d''une fiche n''approuve pas une PR GitHub, ne fusionne pas de branche et ne déploie aucun code.', 'revue de code'),
  ('security.console', '[{"key":"asset","label":"Ressource ciblée","type":"text","required":true},{"key":"environment","label":"Environnement d''intervention","type":"text","required":true},{"key":"finding","label":"Justification et risque","type":"textarea","required":true},{"key":"action","label":"Procédure d''intervention envisagée","type":"textarea","required":true},{"key":"verification","label":"Preuves d''exécution et de contrôle","type":"textarea","required":false},{"key":"review_date","label":"Date d''intervention ou de revue","type":"date","required":false},{"key":"change_ticket","label":"Référence de changement","type":"text","required":false},{"key":"authorized_operator","label":"Intervenant habilité","type":"text","required":false},{"key":"approval_reference","label":"Autorisation préalable","type":"text","required":false},{"key":"rollback_reference","label":"Procédure de retour arrière","type":"text","required":false}]'::jsonb, 'Suivi des opérations techniques sensibles et de leur autorisation préalable.', 'Cette interface est un registre d''interventions ; elle n''exécute aucune commande serveur, suppression, rotation de clé ou déploiement.', 'intervention technique'),
  ('security.documentation', '[{"key":"asset","label":"Application ou composant documenté","type":"text","required":true},{"key":"environment","label":"Version et environnement","type":"text","required":true},{"key":"finding","label":"Objet, contexte et procédure","type":"textarea","required":true},{"key":"action","label":"Mise à jour documentaire prévue","type":"textarea","required":true},{"key":"verification","label":"Preuve de revue technique","type":"textarea","required":false},{"key":"review_date","label":"Prochaine révision","type":"date","required":false},{"key":"document_reference","label":"Référence Drive ou dépôt","type":"text","required":false},{"key":"technical_reviewer","label":"Relecteur technique","type":"text","required":false},{"key":"classification","label":"Niveau de confidentialité","type":"text","required":false},{"key":"runbook_url","label":"Référence du runbook","type":"text","required":false}]'::jsonb, 'Documentation technique contrôlée, runbooks et traçabilité des révisions.', 'Le dossier ne remplace pas le document versionné ni les autorisations Drive ; aucune documentation confidentielle n''est publiée automatiquement.', 'document technique'),
